package ru.multibrowser

import android.content.Context
import java.util.Locale

/** Переводы интерфейса. Язык берётся из настроек или из языка телефона. */
object Tr {
    val CODES = listOf("system", "en", "ru", "es", "pt", "fr", "de", "ar", "hi", "tr", "zh", "be", "uz", "ky", "tg", "kk", "hy")
    val NAMES = mapOf("en" to "English", "ru" to "Русский", "es" to "Español", "pt" to "Português", "fr" to "Français", "de" to "Deutsch", "ar" to "العربية", "hi" to "हिन्दी", "tr" to "Türkçe", "zh" to "中文", "be" to "Беларуская", "uz" to "Oʻzbekcha", "ky" to "Кыргызча", "tg" to "Тоҷикӣ", "kk" to "Қазақша", "hy" to "Հայերեն")
    /** Языки в порядке столбцов таблиц Tr*.kt. */
    val SUPPORTED = CODES.drop(1)
    val RTL = setOf("ar")

    internal var lang = "en" // internal — для модульных тестов

    fun isRtl() = lang in RTL

    /** Определить язык из настроек; "system" → язык телефона, если поддержан, иначе английский. */
    fun apply(ctx: Context) {
        val chosen = Settings.language(ctx)
        lang = if (chosen == "system") {
            val dev = Locale.getDefault().language
            if (dev in SUPPORTED) dev else "en"
        } else if (chosen in SUPPORTED) chosen else "en"
    }

    private val idx = SUPPORTED.withIndex().associate { (i, c) -> c to i }

    /**
     * Текст, сохранённый как ключ перевода («@ex_work_name») — так хранятся примеры первого запуска,
     * чтобы они меняли язык вместе с интерфейсом, пока пользователь их не переименовал.
     */
    fun local(stored: String?): String? = if (stored != null && stored.startsWith("@")) t(stored.drop(1)) else stored

    fun t(key: String, vararg args: Any?): String {
        val row = M[key] ?: return key
        val s = row.getOrNull(idx[lang] ?: 0) ?: row[0]
        return if (args.isEmpty()) s else String.format(s, *args)
    }

